/* @lc app=leetcode id=1386 lang=kotlin */ class Solution { fun maxNumberOfFamilies(n: Int, reservedSeats: Array<IntArray>): Int = reservedSeats.groupBy({ it[0] }, { it[1] }).values.map { s -> (2..5).none { it in s }.let { l -> (6..9).none { it in s }.let { r -> if (l && r) 2 else if (l || r || (4..7).none { it in s }) 1 else 0 } } }.sum() + 2 * (n - reservedSeats.map { it[0] }.distinct().size) }